# Download 2024 general election results from NC State Board of Elections
results_url &lt;- "https://s3.amazonaws.com/dl.ncsbe.gov/ENRS/2024_11_05/results_pct_20241105.zip"

raw_results &lt;- read_tsv(results_url, show_col_types = FALSE)

# Calculate total votes per county for Republican and Democrat presidential choices
county_winners &lt;- raw_results |&gt;
  filter(`Contest Name` == "US PRESIDENT") |&gt;
  filter(`Choice Party` %in% c("REP", "DEM")) |&gt;
  group_by(County, `Choice Party`) |&gt;
  summarize(total_votes = sum(`Total Votes`), .groups = "drop") |&gt;
  pivot_wider(names_from = `Choice Party`, values_from = total_votes, values_fill = 0) |&gt;
  mutate(
    Winner = if_else(REP &gt; DEM, "Republican", "Democrat"),
    County = toupper(County)
  )

# Join winner data with North Carolina county boundaries
nc_map &lt;- read_sf(system.file("shape/nc.shp", package = "sf")) |&gt;
  mutate(County = toupper(NAME)) |&gt;
  left_join(county_winners, by = "County")


ggplot(nc_map) +
  geom_sf(aes(fill = Winner), color = "white", linewidth = 0.2) +
  scale_fill_manual(
    values = c("Democrat" = "blue", "Republican" = "red")
  ) +
  theme_void() +
  labs(
    title = "2024 North Carolina Presidential Election Results by County",
    fill = "Party"
  )
